html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro clock(value) -%}{{ frappe.utils.format_datetime(value, "dd-MM-yyyy HH:mm") if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro person(employee) -%}{{ v(frappe.db.get_value("Employee", employee, "employee_name") if employee else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:g}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro zero(value) -%}{{ "{:g}".format((value or 0) | float) }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
<style>
.lpl-paper { font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #000; line-height: 1.5; }
.lpl-paper p { margin: 0 0 9px; }
.lpl-paper table { width: 100%; border-collapse: collapse; }
.lpl-paper tr { page-break-inside: avoid; }
.lpl-paper .ref { margin: 0 0 18px; }
.lpl-paper .ref td { border: 1px solid #000; padding: 5px 8px; vertical-align: middle; font-size: 11px; }
.lpl-paper .ref .co { text-align: center; font-size: 14px; font-weight: bold; }
.lpl-paper .ref .title { font-size: 12.5px; text-align: center; }
.lpl-paper .rows { margin: 0 0 14px; }
.lpl-paper .rows th, .lpl-paper .rows td { border: 1px solid #000; padding: 4px 7px; text-align: left;
  vertical-align: top; }
.lpl-paper .rows th { font-weight: bold; }
.lpl-paper .line { margin: 0 0 12px; }
.lpl-paper .fill { border-bottom: 1px dotted #000; display: inline-block; min-width: 110px; padding: 0 4px;
  min-height: 16px; vertical-align: bottom; }
.lpl-paper .w0 { min-width: 34px; }
.lpl-paper .w1 { min-width: 70px; }
.lpl-paper .w15 { min-width: 96px; }
.lpl-paper .w2 { min-width: 130px; }
.lpl-paper .w3 { min-width: 210px; }
.lpl-paper .w4 { min-width: 330px; }
.lpl-paper .box { border: 1px solid #000; min-height: 44px; padding: 5px 7px; margin: 0 0 14px;
  white-space: pre-wrap; }
.lpl-paper .sign { margin: 26px 0 14px; }
.lpl-paper .sign td { width: 50%; padding: 0 22px 0 0; vertical-align: top; border: none; }
.lpl-paper .sign .name { min-height: 18px; font-weight: bold; }
.lpl-paper .sign .rule { border-top: 1px solid #000; padding-top: 3px; }
.lpl-paper .said { font-style: italic; margin: 2px 0 0; }
.lpl-paper h4 { font-size: 12px; font-weight: bold; margin: 16px 0 9px; }
.lpl-paper .tick { display: inline-block; width: 28px; height: 19px; border: 1px solid #000; text-align: center;
  line-height: 19px; vertical-align: middle; margin: 0 8px 0 0; font-weight: bold; }
.lpl-paper .types td { border: none; padding: 3px 0; vertical-align: middle; }
.lpl-paper .state { font-weight: normal; }
/* A site's print styles pad every table cell (6px in Frappe's standard.css,
   10px in its Redesign style), grey and lighten every heading cell, and set
   the font on cells, divs and spans, all with !important or on the element
   itself. These say it again under .print-format, so the forms print as
   drawn whatever Print Style is chosen. */
.print-format .lpl-paper, .print-format .lpl-paper td, .print-format .lpl-paper th, .print-format .lpl-paper div,
.print-format .lpl-paper span, .print-format .lpl-paper p, .print-format .lpl-paper h4, .print-format .lpl-paper b {
  font-family: Arial, Helvetica, sans-serif !important; color: #000 !important; }
.print-format .lpl-paper td, .print-format .lpl-paper th { padding: 4px 7px !important; font-size: 12px;
  background-color: transparent !important; }
.print-format .lpl-paper th { font-weight: bold !important; }
.print-format .lpl-paper .rows th { border: 1px solid #000 !important; }
.print-format .lpl-paper .ref td { padding: 5px 8px !important; vertical-align: middle !important; font-size: 11px; }
.print-format .lpl-paper .ref td.co { font-size: 14px; }
.print-format .lpl-paper .ref td.title { font-size: 12.5px; }
.print-format .lpl-paper .sign td { padding: 0 22px 0 0 !important; }
.print-format .lpl-paper .types td { padding: 3px 0 !important; vertical-align: middle !important; }
.print-format .lpl-paper p.line { margin: 0 0 12px; }
</style>
<div class="lpl-paper">
<table class="ref">
<tr><td rowspan="2" style="width:24%">{% if logo %}<img src="{{ logo }}" style="max-height:46px">{% endif %}</td>
<td class="co">LUUKA PLASTICS LTD</td>
<td rowspan="2" style="width:27%">Doc No: LPL/HR/14<br>Rev: 0<br>Issue Date: 31.07.2017</td></tr>
<tr><td class="title">Title: <b>OVERTIME REQUEST FORM</b></td></tr>
</table>
<p class="line"><b>Overtime on:</b> <span class="fill w2">{{ day(doc.overtime_date) }}</span>
&nbsp; <b>Section:</b> <span class="fill w3">{{ v(doc.section) }}</span>
&nbsp; <b>No.</b> <span class="fill w2">{{ v(doc.name) }}</span></p>
<table class="rows">
<tr><th style="width:7%">No.</th><th>NAMES</th><th style="width:24%">SECTION</th>
<th style="width:15%">DURATION</th><th style="width:17%">Employment</th></tr>
{%- for row in doc.employees %}
<tr><td>{{ loop.index }}</td><td>{{ v(row.employee_name) }}</td><td>{{ v(row.section) }}</td>
<td>{{ num(row.hours) }} hrs</td><td>{{ v(row.employment) }}</td></tr>
{%- endfor %}
<tr><th colspan="3" style="text-align:right">Total</th><th>{{ num(doc.total_hours) }} hrs</th><th></th></tr>
</table>
{%- if doc.reason %}
<p class="line"><b>Reason:</b> {{ v(doc.reason) }}</p>
{%- endif %}
<p class="line"><b>Requesting officer:</b> <span class="fill w4">{{ person(doc.requested_by) }}</span>
&nbsp; <b>Date:</b> <span class="fill w2">{{ day(doc.requested_on) }}</span></p>
{%- if doc.status == "Rejected" %}
<p class="line"><b>NOT AUTHORISED:</b> <span class="fill w4">{{ who(doc.authorised_by) }}</span>
&nbsp; <b>Date:</b> <span class="fill w2">{{ day(doc.authorised_on) }}</span></p>
{%- else %}
<p class="line"><b>AUTHORISED BY:</b> <span class="fill w4">{{ who(doc.authorised_by) }}</span>
&nbsp; <b>Date:</b> <span class="fill w2">{{ day(doc.authorised_on) }}</span></p>
{%- endif %}
{%- if doc.authority_remarks %}
<p class="line said">{{ v(doc.authority_remarks) }}</p>
{%- endif %}
<table class="rows">
<tr><th colspan="2">HR USE ONLY: Please provide food coupon to:</th></tr>
<tr><td style="width:32%">Casuals</td><td>{{ doc.coupons_casual or 0 }}</td></tr>
<tr><td>Permanent Staff</td><td>{{ doc.coupons_permanent or 0 }}</td></tr>
</table>
{%- if doc.coupons_issued %}
<p class="line">Coupons issued by {{ who(doc.coupons_by) }} on {{ day(doc.coupons_on) }}.</p>
{%- endif %}
</div>
